from math import exp

pairs = {
    "clear win": (0.9, -0.6),
    "slight edge": (0.27, 0.15),
    "tie": (0.4, 0.4),
    "backwards": (-0.2, 0.5),
}

confidence = {}
for name, (r_chosen, r_rejected) in pairs.items():
    margin = round(r_chosen - r_rejected, 4)
    prob = round(1 / (1 + exp(-margin)), 4)
    confidence[name] = (margin, prob)

for name, (margin, prob) in confidence.items():
    print(f"{name:12} margin {margin:+.2f} -> P(chosen wins) {prob}")
